 "content": "from collections import Counter, defaultdict


def transform(grid):
    out = [row[:] for row in grid]
    # Infer the repeating horizontal color cycle from adjacent cells in the patterned field.
    transitions = defaultdict(Counter)
    colors = Counter()
    for r in range(3, len(grid)):
        for c in range(3, len(grid[0])):
            v = grid[r][c]
            if v:
                colors[v] += 1
                if c + 1 < len(grid[0]) and grid[r][c + 1]:
                    transitions[v][grid[r][c + 1]] += 1
    successor = {v: cnt.most_common(1)[0][0] for v, cnt in transitions.items()}
    # A predecessor map permits filling a hole when only its right edge is visible.
    predecessor = {b: a for a, b in successor.items()}

    for r in range(len(grid)):
        for c in range(len(grid[0])):
            if grid[r][c] != 0:
                continue
            if r < 2:
                out[r][c] = 1
            elif r == 2:
                out[r][c] = 1 if c < 2 else 4
            elif c < 2:
                out[r][c] = 1
            elif c == 2:
                out[r][c] = 4
            else:
                # Walk back from the nearest visible patterned cell to establish phase.
                right = next((j for j in range(c + 1, len(grid[0])) if grid[r][j] != 0), None)
                left = next((j for j in range(c - 1, 2, -1) if grid[r][j] != 0), None)
                if left is not None:
                    val = grid[r][left]
                    for _ in range(c - left):
                        val = successor.get(val, val)
                    out[r][c] = val
                elif right is not None:
                    val = grid[r][right]
                    for _ in range(right - c):
                        val = predecessor.get(val, val)
                    out[r][c] = val
    return out
